// node tests/cases/generate.js <name>: prints a Rust test file pinning
// what Node's Intl gives for each expression in cases/<name>.js.
//
// An entry is an expression, or `{ expression, expected, why }` where
// ICU4X's CLDR data or algorithm gives a different, equally valid
// answer than V8's ICU4C: the answer is pinned with the reason beside
// it, so a change on either side shows up here.
const name = process.argv[2];
const cases = require(`./${name}.js`);
const lines = [
  "// @generated by tests/cases/generate.js from what Node gives; do not edit.",
  "mod support;",
  "",
  "const CASES: &[(&str, &str)] = &[",
];
for (const entry of cases) {
  const expression = typeof entry === "string" ? entry : entry.expression;
  let value;
  try {
    value = String(eval(`(() => ${expression})()`));
  } catch (e) {
    value = `${e.name}: ${e.message}`;
  }
  if (typeof entry !== "string") {
    lines.push(`  // Node gives ${rust(value)}: ${entry.why}`);
    value = entry.expected;
  }
  lines.push(`  (${rust(expression)}, ${rust(value)}),`);
}
lines.push("];", "", "#[test]", `fn ${name}_matches_node() {`, "  support::check(CASES);", "}", "");
// A Rust string literal: JSON's escapes, as Rust spells them, and
// combining marks escaped so the source stays NFC.
function rust(value) {
  return JSON.stringify(value)
    .replace(/\\u([0-9a-fA-F]{4})/g, "\\u{$1}")
    .replace(/[\u0300-\u036f]/g, (c) => `\\u{${c.codePointAt(0).toString(16)}}`);
}
console.log(lines.join("\n"));
